    new_y12 = y12 + delta
    new_y9 = y9 + delta

    # Boundary check: blocks must stay within grid
    if new_y12 < 0 or new_y12 + 4 >= height:
        return nxt

    # Erase old blocks
    for y in range(y12, y12+2):
        for x in range(x12, x12+5):
            grid[y][x] = 3
    for y in range(y9, y9+3):
